@admin.action(description="Cancel partner payouts")
def cancel_selected_payouts(modeladmin, request, queryset):
    cancelled_count = queryset.filter(status='pending').update(status='cancelled')
    modeladmin.message_user(request, f"{cancelled_count} payouts cancelled.")
